window.__GG_LITE__ = {"lite-destinations":[{"id":"lalbagh-fort","slug":"lalbagh-fort","name":"Lalbagh Fort","name_bn":"লালবাগ কেল্লা","division":"Dhaka","district":"Dhaka","tags":["heritage","photography","family"],"latitude":23.7203,"longitude":90.4159,"best_time":"November-February; be at the gate by 09:00 to beat tour buses","duration_days":1,"price_range_min":350,"price_range_max":900,"short_description":"A 1678 Mughal fortress-palace in old Dhaka, begun for Prince Muhammad Azam and never completed. Three monuments, a formal garden and a river-facing curtain wall survive inside the ramparts, making it the city's densest dose of Mughal architecture.","short_bn":"১৬৭৮ সালে শায়েস্তা খাঁর পুত্র সুবেদার শাহজাদা মুহাম্মদ আজামের জন্য শুরু হওয়া অসমাপ্ত মুঘল দুর্গ-প্রাসাদ। পরী বিবির সমাধি, শাহিস কাসর, মসজিদ ও বাগান - সব এক প্রাচীরের ভেতরে।","long_description":"A 1678 Mughal fortress-palace in old Dhaka, begun for Prince Muhammad Azam and never completed. Three monuments, a formal garden and a river-facing curtain wall survive inside the ramparts, making it the city's densest dose of Mughal architecture. The unfinished Mughal citadel of 1678 holds the tomb of Pari Bibi, the Shahis Qasr audience hall and a working seventeenth-century mosque inside one walled garden. The site museum displays Mughal coins, arms and Portuguese-era relics recovered during excavation, and an evening sound-and-light show runs on selected weekends.\n\nOn the ground: Tomb of Pari Bibi in black marble; Shahis Qasr hall and river terrace; Fort wall, bastions and Qamara Khan's tomb; Site museum of Mughal arms and coins; Mosque still used five times a day. GHORA GHURI guides rate the heritage, photography, family character of this place as the main reason to build a stop around it.\n\nReaching Lalbagh Fort: Dhaka is within Dhaka city, connected by ride-share, CNG rickshaw, MRT Line 6 and local buses. Air: Hazrat Shahjalal International Airport (30-60 minutes in city traffic). Ground links run through Sayedabad and Gabtoli terminals for onward divisional travel.\n\nStaying over: expect hotels and serviced apartments across Gulshan, Banani, Dhanmondi and Old Dhaka.\n\nPlanning notes: the season window is November-February; be at the gate by 09:00 to beat tour buses. Budget 350-900 BDT per person for a standard guided visit, and allow 1 day(s) on the ground. Bring water, a hat and patience: most brick monuments are open, shaded by little more than their own arcades, and a guide reads the site far better than any plaque.\n\nAll rates, opening hours and transport times in this listing are indicative and should be confirmed with Lalbagh Fort site authorities before travel. GHORA GHURI keeps a local contact on call for Dhaka division itineraries and can arrange licensed guides, boat contracts and permits where they apply.","highlights":["Tomb of Pari Bibi in black marble","Shahis Qasr hall and river terrace","Fort wall, bastions and Qamara Khan's tomb","Site museum of Mughal arms and coins","Mosque still used five times a day"],"hook":"The unfinished Mughal citadel of 1678 holds the tomb of Pari Bibi, the Shahis Qasr audience hall and a working seventeenth-century mosque inside one walled garden.","arrive":null,"stay":null,"plan":null,"extras":"The site museum displays Mughal coins, arms and Portuguese-era relics recovered during excavation, and an evening sound-and-light show runs on selected weekends.","commons_category":"","featured":true,"image":"assets/images/destinations/lalbagh-fort.jpg","image_thumb":"assets/images/destinations/lalbagh-fort.thumb.jpg","image_remote":"","photo_credit":{"title":"File:Lalbagh Kella (Lalbagh Fort) Dhaka Bangladesh 2011 15.JPG","artist":"Shmunmun","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Lalbagh_Kella_(Lalbagh_Fort)_Dhaka_Bangladesh_2011_15.JPG"},"gallery":[{"local":"assets/images/destinations/lalbagh-fort.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/Lalbagh_Kella_%28Lalbagh_Fort%29_Dhaka_Bangladesh_2011_15.JPG/1920px-Lalbagh_Kella_%28Lalbagh_Fort%29_Dhaka_Bangladesh_2011_15.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Lalbagh Fort, Dhaka"},{"local":"assets/images/destinations/lalbagh-fort.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/Lalbagh_Kella_%28Lalbagh_Fort%29_Dhaka_Bangladesh_2011_15.JPG/1920px-Lalbagh_Kella_%28Lalbagh_Fort%29_Dhaka_Bangladesh_2011_15.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Lalbagh Fort, Dhaka"},{"local":"assets/images/destinations/lalbagh-fort.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/Lalbagh_Kella_%28Lalbagh_Fort%29_Dhaka_Bangladesh_2011_15.JPG/1920px-Lalbagh_Kella_%28Lalbagh_Fort%29_Dhaka_Bangladesh_2011_15.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Lalbagh Fort, Dhaka"}],"video_embed":"","sample_itinerary":[{"title":"Arrive, orient, first look","detail":"Reach Lalbagh Fort by road. Settle in, then a short first walk at Tomb of Pari Bibi in black marble before dinner in town. The guide briefs you on timings, ticket counters and where the light works late in the day."},{"title":"Slow morning and departure","detail":"Breakfast, one last look at Tomb of Pari Bibi in black marble, then the return leg. Best time to be here is November-February; be at the gate by 09:00 to beat tour buses, so plan the drive or boat around that window rather than the reverse."}]},{"id":"ahsan-manzil","slug":"ahsan-manzil","name":"Ahsan Manzil","name_bn":"আহসান মঞ্জিল","division":"Dhaka","district":"Dhaka","tags":["heritage","museum","photography"],"latitude":23.73,"longitude":90.4206,"best_time":"November-February; closed to visitors on the last Friday of each month","duration_days":1,"price_range_min":250,"price_range_max":700,"short_description":"The 1872 palace of the Nawabs of Dhaka on the Buriganga, now a national museum. Its dome, marble staircase and river terrace anchor the old city skyline and pair naturally with Sadarghat, Islam Bagh and the Armenian church.","short_bn":"বুড়িগঙ্গার তীরে ১৮৭২ সালে ঢাকার নবাবের ভোগ করা গোলাপি প্রাসাদ, এখন জাতীয় সংগ্রহশালা। নদীমুখী বারান্দা, সাদা মার্বেল সিঁড়ি আর গম্বুজ পুরান ঢাকার সবচেয়ে পরিচিত দৃশ্য।","long_description":"The 1872 palace of the Nawabs of Dhaka on the Buriganga, now a national museum. Its dome, marble staircase and river terrace anchor the old city skyline and pair naturally with Sadarghat, Islam Bagh and the Armenian church. The 'Pink Palace' of the Nawabs of Dhaka rose in 1872 after a tornado levelled the river-front house of Sheikh Saheedullah, and its dome is visible from most of old Dhaka. Twenty-odd galleries trace the Nawab family, the 1878 'Murar Chand' case and Dhaka's boat and jute trade, while the state rooms keep their original staircase, chandeliers and marble fountain.\n\nOn the ground: Durbar hall with Belgian chandeliers; Nawab portraits, regalia and medals; Museum galleries on Old Dhaka river trade; Buriganga terrace and riverside garden; Boat view of the facade from Sadarghat side. GHORA GHURI guides rate the heritage, museum, photography character of this place as the main reason to build a stop around it.\n\nReaching Ahsan Manzil: Dhaka is within Dhaka city, connected by ride-share, CNG rickshaw, MRT Line 6 and local buses. Air: Hazrat Shahjalal International Airport (30-60 minutes in city traffic). Ground links run through Sayedabad and Gabtoli terminals for onward divisional travel.\n\nStaying over: expect hotels and serviced apartments across Gulshan, Banani, Dhanmondi and Old Dhaka.\n\nPlanning notes: the season window is November-February; closed to visitors on the last Friday of each month. Budget 250-700 BDT per person for a standard guided visit, and allow 1 day(s) on the ground. Bring water, a hat and patience: most brick monuments are open, shaded by little more than their own arcades, and a guide reads the site far better than any plaque.\n\nAll rates, opening hours and transport times in this listing are indicative and should be confirmed with Ahsan Manzil site authorities before travel. GHORA GHURI keeps a local contact on call for Dhaka division itineraries and can arrange licensed guides, boat contracts and permits where they apply.","highlights":["Durbar hall with Belgian chandeliers","Nawab portraits, regalia and medals","Museum galleries on Old Dhaka river trade","Buriganga terrace and riverside garden","Boat view of the facade from Sadarghat side"],"hook":"The 'Pink Palace' of the Nawabs of Dhaka rose in 1872 after a tornado levelled the river-front house of Sheikh Saheedullah, and its dome is visible from most of old Dhaka.","arrive":null,"stay":null,"plan":null,"extras":"Twenty-odd galleries trace the Nawab family, the 1878 'Murar Chand' case and Dhaka's boat and jute trade, while the state rooms keep their original staircase, chandeliers and marble fountain.","commons_category":"","featured":true,"image":"assets/images/destinations/ahsan-manzil.jpg","image_thumb":"assets/images/destinations/ahsan-manzil.thumb.jpg","image_remote":"","photo_credit":{"title":"File:Ahsan Manjil Front View.jpg","artist":"Samiha Ahmed Rafa","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ahsan_Manjil_Front_View.jpg"},"gallery":[{"local":"assets/images/destinations/ahsan-manzil.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/3/30/Ahsan_Manjil_Front_View.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","alt":"Ahsan Manzil, Dhaka"},{"local":"assets/images/destinations/ahsan-manzil.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/3/30/Ahsan_Manjil_Front_View.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","alt":"Ahsan Manzil, Dhaka"},{"local":"assets/images/destinations/ahsan-manzil.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/3/30/Ahsan_Manjil_Front_View.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","alt":"Ahsan Manzil, Dhaka"}],"video_embed":"","sample_itinerary":[{"title":"Arrive, orient, first look","detail":"Reach Ahsan Manzil by road. Settle in, then a short first walk at Durbar hall with Belgian chandeliers before dinner in town. The guide briefs you on timings, ticket counters and where the light works late in the day."},{"title":"Slow morning and departure","detail":"Breakfast, one last look at Durbar hall with Belgian chandeliers, then the return leg. Best time to be here is November-February; closed to visitors on the last Friday of each month, so plan the drive or boat around that window rather than the reverse."}]},{"id":"sonargaon-panam-city","slug":"sonargaon-panam-city","name":"Sonargaon & Panam City","name_bn":"সোনারগাঁও ও পানাম সিটি","division":"Dhaka","district":"Narayanganj","tags":["heritage","village","photography"],"latitude":23.6797,"longitude":90.5803,"best_time":"October-March; the folk museum closes on Sundays","duration_days":1,"price_range_min":400,"price_range_max":1100,"short_description":"Sonargaon layers a sultanate capital, a nineteenth-century Hindu trading town and one of Bengal's best village museums within a single rickshaw ride of Dhaka. Panam City's decaying brick facades make the most photographed heritage street outside old Dhaka.","short_bn":"ঢাকার আগে বাংলা সালতানাতের রাজধানী সোনারগাঁ - সুলতানি সমাধি, ঊনবিংশ শতাব্দীর হিন্দু ব্যবসায়ীদের পানাম সিটি আর দেশের সেরা গ্রামীণ শিল্প জাদুঘর, ঢাকা থেকে আধা দিনের ভ্রমণে।","long_description":"Sonargaon layers a sultanate capital, a nineteenth-century Hindu trading town and one of Bengal's best village museums within a single rickshaw ride of Dhaka. Panam City's decaying brick facades make the most photographed heritage street outside old Dhaka. Capital of the medieval Sultanate of Bengal before Dhaka, Sonargaon keeps a Hindu-Buddhist bridge, sultanate tombs and the abandoned brick trading street of Panam City. The Sonargaon Folk Art & Craft Museum is the best-run village museum in the country, with bamboo, cane, terracotta and jute displays plus live weavers on selected days.\n\nOn the ground: Panam City's merchant mansions; Sonargaon Folk Art & Craft Museum; Tomb of Sultan Ghiyasuddin Azam Shah; Shah Zafar and Shah Quamir tombs; Old brick bridge over the Sitalakshya. GHORA GHURI guides rate the heritage, village, photography character of this place as the main reason to build a stop around it.\n\nReaching Sonargaon & Panam City: Narayanganj is 45-75 minutes from central Dhaka via Jagannathganj or the Padma bridge route. Air: Shahjalal International Airport, about 40 minutes. Ground links run through Armanitola and Bandar bus stands, plus launch ghats on the Shitalakshya.\n\nStaying over: expect a handful of business hotels near Bandar and Khulshi junction.\n\nPlanning notes: the season window is October-March; the folk museum closes on Sundays. Budget 400-1,100 BDT per person for a standard guided visit, and allow 1 day(s) on the ground. Bring water, a hat and patience: most brick monuments are open, shaded by little more than their own arcades, and a guide reads the site far better than any plaque.\n\nAll rates, opening hours and transport times in this listing are indicative and should be confirmed with Sonargaon & Panam City site authorities before travel. GHORA GHURI keeps a local contact on call for Dhaka division itineraries and can arrange licensed guides, boat contracts and permits where they apply.","highlights":["Panam City's merchant mansions","Sonargaon Folk Art & Craft Museum","Tomb of Sultan Ghiyasuddin Azam Shah","Shah Zafar and Shah Quamir tombs","Old brick bridge over the Sitalakshya"],"hook":"Capital of the medieval Sultanate of Bengal before Dhaka, Sonargaon keeps a Hindu-Buddhist bridge, sultanate tombs and the abandoned brick trading street of Panam City.","arrive":null,"stay":null,"plan":null,"extras":"The Sonargaon Folk Art & Craft Museum is the best-run village museum in the country, with bamboo, cane, terracotta and jute displays plus live weavers on selected days.","commons_category":"","featured":false,"image":"assets/images/destinations/sonargaon-panam-city.jpg","image_thumb":"assets/images/destinations/sonargaon-panam-city.thumb.jpg","image_remote":"","photo_credit":{"title":"File:Panam Bridge, Sonargaon (116).jpg","artist":"Nasir Khan Saikat","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Panam_Bridge,_Sonargaon_(116).jpg"},"gallery":[{"local":"assets/images/destinations/sonargaon-panam-city.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Panam_Bridge%2C_Sonargaon_%28116%29.jpg/1920px-Panam_Bridge%2C_Sonargaon_%28116%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Sonargaon & Panam City, Narayanganj"},{"local":"assets/images/destinations/sonargaon-panam-city.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Panam_Bridge%2C_Sonargaon_%28116%29.jpg/1920px-Panam_Bridge%2C_Sonargaon_%28116%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Sonargaon & Panam City, Narayanganj"},{"local":"assets/images/destinations/sonargaon-panam-city.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Panam_Bridge%2C_Sonargaon_%28116%29.jpg/1920px-Panam_Bridge%2C_Sonargaon_%28116%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Sonargaon & Panam City, Narayanganj"}],"video_embed":"","sample_itinerary":[{"title":"Arrive, orient, first look","detail":"Reach Sonargaon & Panam City by road. Settle in, then a short first walk at Panam City's merchant mansions before dinner in town. The guide briefs you on timings, ticket counters and where the light works late in the day."},{"title":"Slow morning and departure","detail":"Breakfast, one last look at Panam City's merchant mansions, then the return leg. Best time to be here is October-March; the folk museum closes on Sundays, so plan the drive or boat around that window rather than the reverse."}]},{"id":"goaldi-mosque","slug":"goaldi-mosque","name":"Goaldi Mosque & Sultanate Tombs","name_bn":"গোয়াল্ডী মসজিদ","division":"Dhaka","district":"Narayanganj","tags":["heritage","architecture","offbeat"],"latitude":23.6683,"longitude":90.5347,"best_time":"November-February; morning light on the terracotta","duration_days":1,"price_range_min":200,"price_range_max":600,"short_description":"Goaldi Mosque, built in 1519 by Sultan Husain Shah's governor, is the jewel of Old Sonargaon: a terracotta-clad single-domed prayer hall on UNESCO's tentative list, sitting quietly amid village lanes few tourists ever find.","short_bn":"১৫১৯ সালের হুসাইন শাহী আমলের এক গম্বুজের মসজিদ গোয়াল্ডী - টেরাকোটায় মোড়া মিহরাব, ইউনেস্কো তারিকা তালিকায় নাম, আর সোনারগাঁওয়ের গ্রামের ভেতরে প্রায় নির্জন পরিবেশ।","long_description":"Goaldi Mosque, built in 1519 by Sultan Husain Shah's governor, is the jewel of Old Sonargaon: a terracotta-clad single-domed prayer hall on UNESCO's tentative list, sitting quietly amid village lanes few tourists ever find. A small 1519 single-domed mosque at Old Sonargaon, on UNESCO's tentative list, with some of the finest terracotta rosettes surviving from the Husain Shahi period. Combine with Panam City and the Adina-style tombs nearby for a compact sultanate morning; the site is open, unfenced and usually empty apart from Friday prayers.\n\nOn the ground: Single dome on twelve arched entrances; Terracotta floral rosettes and mihrab; UNESCO tentative-listed monument; Adjacent royal tombs of the 1400s; Walking distance from Sonargaon museum. GHORA GHURI guides rate the heritage, architecture, offbeat character of this place as the main reason to build a stop around it.\n\nReaching Goaldi Mosque & Sultanate Tombs: Narayanganj is 45-75 minutes from central Dhaka via Jagannathganj or the Padma bridge route. Air: Shahjalal International Airport, about 40 minutes. Ground links run through Armanitola and Bandar bus stands, plus launch ghats on the Shitalakshya.\n\nStaying over: expect a handful of business hotels near Bandar and Khulshi junction.\n\nPlanning notes: the season window is November-February; morning light on the terracotta. Budget 200-600 BDT per person for a standard guided visit, and allow 1 day(s) on the ground. Bring water, a hat and patience: most brick monuments are open, shaded by little more than their own arcades, and a guide reads the site far better than any plaque.\n\nAll rates, opening hours and transport times in this listing are indicative and should be confirmed with Goaldi Mosque & Sultanate Tombs site authorities before travel. GHORA GHURI keeps a local contact on call for Dhaka division itineraries and can arrange licensed guides, boat contracts and permits where they apply.","highlights":["Single dome on twelve arched entrances","Terracotta floral rosettes and mihrab","UNESCO tentative-listed monument","Adjacent royal tombs of the 1400s","Walking distance from Sonargaon museum"],"hook":"A small 1519 single-domed mosque at Old Sonargaon, on UNESCO's tentative list, with some of the finest terracotta rosettes surviving from the Husain Shahi period.","arrive":null,"stay":null,"plan":null,"extras":"Combine with Panam City and the Adina-style tombs nearby for a compact sultanate morning; the site is open, unfenced and usually empty apart from Friday prayers.","commons_category":"","featured":false,"image":"assets/images/destinations/goaldi-mosque.jpg","image_thumb":"assets/images/destinations/goaldi-mosque.thumb.jpg","image_remote":"","photo_credit":{"title":"File:Pillar design, Goaldi mosque, Sonargaon, Narayanganj.jpg","artist":"Ferdous","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Pillar_design,_Goaldi_mosque,_Sonargaon,_Narayanganj.jpg"},"gallery":[{"local":"assets/images/destinations/goaldi-mosque.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/2/20/Pillar_design%2C_Goaldi_mosque%2C_Sonargaon%2C_Narayanganj.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","alt":"Goaldi Mosque & Sultanate Tombs, Narayanganj"},{"local":"assets/images/destinations/goaldi-mosque.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/2/20/Pillar_design%2C_Goaldi_mosque%2C_Sonargaon%2C_Narayanganj.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","alt":"Goaldi Mosque & Sultanate Tombs, Narayanganj"},{"local":"assets/images/destinations/goaldi-mosque.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/2/20/Pillar_design%2C_Goaldi_mosque%2C_Sonargaon%2C_Narayanganj.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","alt":"Goaldi Mosque & Sultanate Tombs, Narayanganj"}],"video_embed":"","sample_itinerary":[{"title":"Arrive, orient, first look","detail":"Reach Goaldi Mosque & Sultanate Tombs by road. Settle in, then a short first walk at Single dome on twelve arched entrances before dinner in town. The guide briefs you on timings, ticket counters and where the light works late in the day."},{"title":"Slow morning and departure","detail":"Breakfast, one last look at Single dome on twelve arched entrances, then the return leg. Best time to be here is November-February; morning light on the terracotta, so plan the drive or boat around that window rather than the reverse."}]},{"id":"bangladesh-national-museum","slug":"bangladesh-national-museum","name":"Bangladesh National Museum","name_bn":"বাংলাদেশ জাতীয় জাদুঘর","division":"Dhaka","district":"Dhaka","tags":["museum","heritage","family"],"latitude":23.745,"longitude":90.3908,"best_time":"Year-round; Sat-Thu 10:00-18:00, Friday from 15:00 (closed last Friday)","duration_days":1,"price_range_min":200,"price_range_max":600,"short_description":"Dhaka's national museum is the single best indoor start to a Bangladesh trip: terracotta, coinage, textiles, tribal ethnography and the 1971 war room, in a colonnaded Shahbagh building beside the university and the National Zoo.","short_bn":"১৯১৩ সালে প্রতিষ্ঠিত দেশের বৃহত্তম জাদুঘর, শাহবাগ ভবনে পুরাতাত্ত্বিক, শিল্প, লোকজ ও মুক্তিযুদ্ধের নিদর্শন একই ছাদের নিচে - পাল দুর্গা, বৌদ্ধ মূর্তি আর মহাস্থানগড়ের প্রাচীন লিপি সহ।","long_description":"Dhaka's national museum is the single best indoor start to a Bangladesh trip: terracotta, coinage, textiles, tribal ethnography and the 1971 war room, in a colonnaded Shahbagh building beside the university and the National Zoo. Founded in 1913 and moved to the Shahbagh campus in 1983, it holds archaeology, art, ethnography and 1971 history under one roof, including the Pal Durga bronze and the Mahasthangarh stone inscription. The rickshaw-art and boat galleries are the most-quoted rooms; guided heritage walks can string the museum to the Shaheed Minar and the university campus in a single afternoon.\n\nOn the ground: Pal Durga and Buddhist bronzes; Liberation War 1971 gallery; Mahasthangarh stone inscription; Rickshaw, jatra and folk art halls; Boat and rivercraft collection. GHORA GHURI guides rate the museum, heritage, family character of this place as the main reason to build a stop around it.\n\nReaching Bangladesh National Museum: Dhaka is within Dhaka city, connected by ride-share, CNG rickshaw, MRT Line 6 and local buses. Air: Hazrat Shahjalal International Airport (30-60 minutes in city traffic). Ground links run through Sayedabad and Gabtoli terminals for onward divisional travel.\n\nStaying over: expect hotels and serviced apartments across Gulshan, Banani, Dhanmondi and Old Dhaka.\n\nPlanning notes: the season window is Year-round; Sat-Thu 10:00-18:00, Friday from 15:00 (closed last Friday). Budget 200-600 BDT per person for a standard guided visit, and allow 1 day(s) on the ground. Photography rules and opening days change often - confirm on the day, and allow the closing lunch hour, which many public museums still observe.\n\nAll rates, opening hours and transport times in this listing are indicative and should be confirmed with Bangladesh National Museum site authorities before travel. GHORA GHURI keeps a local contact on call for Dhaka division itineraries and can arrange licensed guides, boat contracts and permits where they apply.","highlights":["Pal Durga and Buddhist bronzes","Liberation War 1971 gallery","Mahasthangarh stone inscription","Rickshaw, jatra and folk art halls","Boat and rivercraft collection"],"hook":"Founded in 1913 and moved to the Shahbagh campus in 1983, it holds archaeology, art, ethnography and 1971 history under one roof, including the Pal Durga bronze and the Mahasthangarh stone inscription.","arrive":null,"stay":null,"plan":null,"extras":"The rickshaw-art and boat galleries are the most-quoted rooms; guided heritage walks can string the museum to the Shaheed Minar and the university campus in a single afternoon.","commons_category":"","featured":false,"image":"assets/images/destinations/bangladesh-national-museum.jpg","image_thumb":"assets/images/destinations/bangladesh-national-museum.thumb.jpg","image_remote":"","photo_credit":{"title":"File:Bangladesh National Museum in Dhaka 01.jpg","artist":"Tarunsamanta","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Bangladesh_National_Museum_in_Dhaka_01.jpg"},"gallery":[{"local":"assets/images/destinations/bangladesh-national-museum.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Bangladesh_National_Museum_in_Dhaka_01.jpg/1920px-Bangladesh_National_Museum_in_Dhaka_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Bangladesh National Museum, Dhaka"},{"local":"assets/images/destinations/bangladesh-national-museum.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Bangladesh_National_Museum_in_Dhaka_01.jpg/1920px-Bangladesh_National_Museum_in_Dhaka_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Bangladesh National Museum, Dhaka"},{"local":"assets/images/destinations/bangladesh-national-museum.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Bangladesh_National_Museum_in_Dhaka_01.jpg/1920px-Bangladesh_National_Museum_in_Dhaka_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Bangladesh National Museum, Dhaka"}],"video_embed":"","sample_itinerary":[{"title":"Arrive, orient, first look","detail":"Reach Bangladesh National Museum by road. Settle in, then a short first walk at Pal Durga and Buddhist bronzes before dinner in town. The guide briefs you on timings, ticket counters and where the light works late in the day."},{"title":"Slow morning and departure","detail":"Breakfast, one last look at Pal Durga and Buddhist bronzes, then the return leg. Best time to be here is Year-round; Sat-Thu 10:00-18:00, Friday from 15:00 (closed last Friday), so plan the drive or boat around that window rather than the reverse."}]},{"id":"baitul-mukarram","slug":"baitul-mukarram","name":"Baitul Mukarram National Mosque","name_bn":"বাইতুল মোকাররম জাতীয় মসজিদ","division":"Dhaka","district":"Dhaka","tags":["heritage","architecture","city"],"latitude":23.7329,"longitude":90.4146,"best_time":"October-March; visit outside Friday congregational hours","duration_days":1,"price_range_min":0,"price_range_max":400,"short_description":"Dhaka's national mosque at Paltan, a 1968 marble cube that anchors the city's Ramadan and Eid nights. Its courtyard light, the traffic of Gulistan and the old lanes around it make a vivid ten-minute stop in any heritage walk.","short_bn":"১৯৬৮ সালে কাবার আদলে গড়া জাতীয় মসজিদ পল্টনে - রমজানের রাত, সাদা মার্বেল প্রাঙ্গণ আর গুলিস্তানের কোলাহল মিলিয়ে ঢাকার সবচেয়ে পরিচিত দৃশ্যগুলোর একটি।","long_description":"Dhaka's national mosque at Paltan, a 1968 marble cube that anchors the city's Ramadan and Eid nights. Its courtyard light, the traffic of Gulistan and the old lanes around it make a vivid ten-minute stop in any heritage walk. Completed in 1968 on a cube plan echoing the Kaaba, it seats around 40,000 worshippers and remains one of the largest mosques in South Asia. Non-worshippers should dress modestly and photograph from the outer court; the New Market, Gulistan and the Shaheed Minar all fall within a twenty-minute walk.\n\nOn the ground: Kaaba-inspired cubic prayer hall; Open courtyard and ablution pools; Ramadan night congregations; Adjacent New Market and Gulistan; Easy pairing with Shahbagh museums. GHORA GHURI guides rate the heritage, architecture, city character of this place as the main reason to build a stop around it.\n\nReaching Baitul Mukarram National Mosque: Dhaka is within Dhaka city, connected by ride-share, CNG rickshaw, MRT Line 6 and local buses. Air: Hazrat Shahjalal International Airport (30-60 minutes in city traffic). Ground links run through Sayedabad and Gabtoli terminals for onward divisional travel.\n\nStaying over: expect hotels and serviced apartments across Gulshan, Banani, Dhanmondi and Old Dhaka.\n\nPlanning notes: the season window is October-March; visit outside Friday congregational hours. Budget 0-400 BDT per person for a standard guided visit, and allow 1 day(s) on the ground. Bring water, a hat and patience: most brick monuments are open, shaded by little more than their own arcades, and a guide reads the site far better than any plaque.\n\nAll rates, opening hours and transport times in this listing are indicative and should be confirmed with Baitul Mukarram National Mosque site authorities before travel. GHORA GHURI keeps a local contact on call for Dhaka division itineraries and can arrange licensed guides, boat contracts and permits where they apply.","highlights":["Kaaba-inspired cubic prayer hall","Open courtyard and ablution pools","Ramadan night congregations","Adjacent New Market and Gulistan","Easy pairing with Shahbagh museums"],"hook":"Completed in 1968 on a cube plan echoing the Kaaba, it seats around 40,000 worshippers and remains one of the largest mosques in South Asia.","arrive":null,"stay":null,"plan":null,"extras":"Non-worshippers should dress modestly and photograph from the outer court; the New Market, Gulistan and the Shaheed Minar all fall within a twenty-minute walk.","commons_category":"","featured":false,"image":"assets/images/destinations/baitul-mukarram.jpg","image_thumb":"assets/images/destinations/baitul-mukarram.thumb.jpg","image_remote":"","photo_credit":{"title":"File:Eid al-Adha prayers at Baitul Mukarram, Dhaka, Bangladesh, 2023-06-29 (PID-0015139).jpg","artist":"Press Information Department","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Eid_al-Adha_prayers_at_Baitul_Mukarram,_Dhaka,_Bangladesh,_2023-06-29_(PID-0015139).jpg"},"gallery":[{"local":"assets/images/destinations/baitul-mukarram.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Eid_al-Adha_prayers_at_Baitul_Mukarram%2C_Dhaka%2C_Bangladesh%2C_2023-06-29_%28PID-0015139%29.jpg/1920px-Eid_al-Adha_prayers_at_Baitul_Mukarram%2C_Dhaka%2C_Bangladesh%2C_2023-06-29_%28PID-0015139%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Baitul Mukarram National Mosque, Dhaka"},{"local":"assets/images/destinations/baitul-mukarram.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Eid_al-Adha_prayers_at_Baitul_Mukarram%2C_Dhaka%2C_Bangladesh%2C_2023-06-29_%28PID-0015139%29.jpg/1920px-Eid_al-Adha_prayers_at_Baitul_Mukarram%2C_Dhaka%2C_Bangladesh%2C_2023-06-29_%28PID-0015139%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Baitul Mukarram National Mosque, Dhaka"},{"local":"assets/images/destinations/baitul-mukarram.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Eid_al-Adha_prayers_at_Baitul_Mukarram%2C_Dhaka%2C_Bangladesh%2C_2023-06-29_%28PID-0015139%29.jpg/1920px-Eid_al-Adha_prayers_at_Baitul_Mukarram%2C_Dhaka%2C_Bangladesh%2C_2023-06-29_%28PID-0015139%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Baitul Mukarram National Mosque, Dhaka"}],"video_embed":"","sample_itinerary":[{"title":"Arrive, orient, first look","detail":"Reach Baitul Mukarram National Mosque by road. Settle in, then a short first walk at Kaaba-inspired cubic prayer hall before dinner in town. The guide briefs you on timings, ticket counters and where the light works late in the day."},{"title":"Slow morning and departure","detail":"Breakfast, one last look at Kaaba-inspired cubic prayer hall, then the return leg. Best time to be here is October-March; visit outside Friday congregational hours, so plan the drive or boat around that window rather than the reverse."}]},{"id":"islamic-art-museum","slug":"islamic-art-museum","name":"Islamic Art Museum","name_bn":"ইসলামিক আর্ট মিউজিয়াম","division":"Dhaka","district":"Dhaka","tags":["museum","heritage","calligraphy"],"latitude":23.7295,"longitude":90.4198,"best_time":"November-February; Sat-Thu, closed the last Friday of the month","duration_days":1,"price_range_min":150,"price_range_max":500,"short_description":"A compact national museum in old Dhaka, built against the ruins of a 1495 sultanate mosque, with Islamic calligraphy, coins, weapons and textiles. It is the quietest, best-value gallery in the city and free for school groups.","short_bn":"ইসলামপুরের ১৪৯৫ সালের সুলতানি মসজিদের গায়ে গড়া ইসলামিক আর্ট মিউজিয়াম - হস্তলিপি, টাকা, অস্ত্র, টেরাকোটা ও বস্ত্রের ছোট কিন্তু সমৃদ্ধ সংগ্রহ।","long_description":"A compact national museum in old Dhaka, built against the ruins of a 1495 sultanate mosque, with Islamic calligraphy, coins, weapons and textiles. It is the quietest, best-value gallery in the city and free for school groups. Built into the wall of the fifteenth-century Babu Mosque at Islam Bagh, it displays calligraphy, coins, arms, jade and terracotta from the sultanate to the Nawabi period. Thirty minutes covers it, and it anchors the best free half-day walk in old Dhaka alongside the Armenian church, the Subuddhi Bazaar lanes and Sadarghat.\n\nOn the ground: Sultanate terracotta plaques; Qur'an manuscripts and calligraphy; Mughal and Nawabi coinage; Arms, armour and jade inlay; The 1495 Babu Mosque next door. GHORA GHURI guides rate the museum, heritage, calligraphy character of this place as the main reason to build a stop around it.\n\nReaching Islamic Art Museum: Dhaka is within Dhaka city, connected by ride-share, CNG rickshaw, MRT Line 6 and local buses. Air: Hazrat Shahjalal International Airport (30-60 minutes in city traffic). Ground links run through Sayedabad and Gabtoli terminals for onward divisional travel.\n\nStaying over: expect hotels and serviced apartments across Gulshan, Banani, Dhanmondi and Old Dhaka.\n\nPlanning notes: the season window is November-February; Sat-Thu, closed the last Friday of the month. Budget 150-500 BDT per person for a standard guided visit, and allow 1 day(s) on the ground. Photography rules and opening days change often - confirm on the day, and allow the closing lunch hour, which many public museums still observe.\n\nAll rates, opening hours and transport times in this listing are indicative and should be confirmed with Islamic Art Museum site authorities before travel. GHORA GHURI keeps a local contact on call for Dhaka division itineraries and can arrange licensed guides, boat contracts and permits where they apply.","highlights":["Sultanate terracotta plaques","Qur'an manuscripts and calligraphy","Mughal and Nawabi coinage","Arms, armour and jade inlay","The 1495 Babu Mosque next door"],"hook":"Built into the wall of the fifteenth-century Babu Mosque at Islam Bagh, it displays calligraphy, coins, arms, jade and terracotta from the sultanate to the Nawabi period.","arrive":null,"stay":null,"plan":null,"extras":"Thirty minutes covers it, and it anchors the best free half-day walk in old Dhaka alongside the Armenian church, the Subuddhi Bazaar lanes and Sadarghat.","commons_category":"","featured":false,"image":"","image_thumb":"","image_remote":"","photo_credit":null,"gallery":[{"local":"","remote":"https://picsum.photos/seed/islamic-art-museum-1/1200/800.jpg","alt":"Islamic Art Museum - illustrative view 1"},{"local":"","remote":"https://picsum.photos/seed/islamic-art-museum-2/1200/800.jpg","alt":"Islamic Art Museum - illustrative view 2"},{"local":"","remote":"https://picsum.photos/seed/islamic-art-museum-3/1200/800.jpg","alt":"Islamic Art Museum - illustrative view 3"}],"video_embed":"","sample_itinerary":[{"title":"Arrive, orient, first look","detail":"Reach Islamic Art Museum by road. Settle in, then a short first walk at Sultanate terracotta plaques before dinner in town. The guide briefs you on timings, ticket counters and where the light works late in the day."},{"title":"Slow morning and departure","detail":"Breakfast, one last look at Sultanate terracotta plaques, then the return leg. Best time to be here is November-February; Sat-Thu, closed the last Friday of the month, so plan the drive or boat around that window rather than the reverse."}]},{"id":"sadarghat-buriganga","slug":"sadarghat-buriganga","name":"Sadarghat & Buriganga Riverfront","name_bn":"সদরঘাট ও বুড়িগঙ্গা","division":"Dhaka","district":"Dhaka","tags":["river","city","photography"],"latitude":23.7122,"longitude":90.4106,"best_time":"October-March; take the boat an hour before sunset","duration_days":1,"price_range_min":200,"price_range_max":2200,"short_description":"Dhaka's mother river port at Sadarghat, connecting the delta districts by launch, steamer and wooden cargo boat. Morning loading, evening light on the Buriganga and a cheap crossing make the city's most vivid hour.","short_bn":"ঢাকার বুড়িগঙ্গার সদরঘাট - লঞ্চ, স্টিমার আর হাজার নৌকা নিয়ে নদীমাতৃক বাংলাদেশের সঙ্গে শহরের সংযোগ। ভোরে মালামাল বোঝাই, সন্ধ্যায় নদীর আলো।","long_description":"Dhaka's mother river port at Sadarghat, connecting the delta districts by launch, steamer and wooden cargo boat. Morning loading, evening light on the Buriganga and a cheap crossing make the city's most vivid hour. One of the busiest river ports on earth, where BIWTA launches, steamers and thousands of country boats tie Dhaka to the whole riverine delta. A one-hour steamer towards Munshiganj shows the delta as travellers describe it most often; the covered cargo sheds and the 1867 river-port layout are still legible on foot.\n\nOn the ground: Launch, steamer and country-boat piers; Sunset crossing towards Munshiganj; Colonial cargo sheds and BIWTA buildings; Floating produce markets at dawn; Rickshaw route to Ahsan Manzil from the ghat. GHORA GHURI guides rate the river, city, photography character of this place as the main reason to build a stop around it.\n\nReaching Sadarghat & Buriganga Riverfront: Dhaka is within Dhaka city, connected by ride-share, CNG rickshaw, MRT Line 6 and local buses. Air: Hazrat Shahjalal International Airport (30-60 minutes in city traffic). Ground links run through Sayedabad and Gabtoli terminals for onward divisional travel.\n\nStaying over: expect hotels and serviced apartments across Gulshan, Banani, Dhanmondi and Old Dhaka.\n\nPlanning notes: the season window is October-March; take the boat an hour before sunset. Budget 200-2,200 BDT per person for a standard guided visit, and allow 1 day(s) on the ground. River levels rewrite the map every year: launch timetables, ghats and sandbanks all move. Build a buffer day into any river-based plan.\n\nAll rates, opening hours and transport times in this listing are indicative and should be confirmed with Sadarghat & Buriganga Riverfront site authorities before travel. GHORA GHURI keeps a local contact on call for Dhaka division itineraries and can arrange licensed guides, boat contracts and permits where they apply.","highlights":["Launch, steamer and country-boat piers","Sunset crossing towards Munshiganj","Colonial cargo sheds and BIWTA buildings","Floating produce markets at dawn","Rickshaw route to Ahsan Manzil from the ghat"],"hook":"One of the busiest river ports on earth, where BIWTA launches, steamers and thousands of country boats tie Dhaka to the whole riverine delta.","arrive":null,"stay":null,"plan":null,"extras":"A one-hour steamer towards Munshiganj shows the delta as travellers describe it most often; the covered cargo sheds and the 1867 river-port layout are still legible on foot.","commons_category":"","featured":false,"image":"assets/images/destinations/sadarghat-buriganga.jpg","image_thumb":"assets/images/destinations/sadarghat-buriganga.thumb.jpg","image_remote":"","photo_credit":{"title":"File:At Sadarghat River Port.jpg","artist":"nasir khan","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:At_Sadarghat_River_Port.jpg"},"gallery":[{"local":"assets/images/destinations/sadarghat-buriganga.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/8/87/At_Sadarghat_River_Port.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","alt":"Sadarghat & Buriganga Riverfront, Dhaka"},{"local":"assets/images/destinations/sadarghat-buriganga.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/8/87/At_Sadarghat_River_Port.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","alt":"Sadarghat & Buriganga Riverfront, Dhaka"},{"local":"assets/images/destinations/sadarghat-buriganga.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/8/87/At_Sadarghat_River_Port.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","alt":"Sadarghat & Buriganga Riverfront, Dhaka"}],"video_embed":"","sample_itinerary":[{"title":"Arrive, orient, first look","detail":"Reach Sadarghat & Buriganga Riverfront by road. Settle in, then a short first walk at Launch, steamer and country-boat piers before dinner in town. The guide briefs you on timings, ticket counters and where the light works late in the day."},{"title":"Slow morning and departure","detail":"Breakfast, one last look at Launch, steamer and country-boat piers, then the return leg. Best time to be here is October-March; take the boat an hour before sunset, so plan the drive or boat around that window rather than the reverse."}]},{"id":"dhakeshwari-temple","slug":"dhakeshwari-temple","name":"Dhakeshwari National Temple","name_bn":"ঢাকেশ্বরী জাতীয় মন্দির","division":"Dhaka","district":"Dhaka","tags":["heritage","pilgrimage","architecture"],"latitude":23.7401,"longitude":90.3883,"best_time":"October-March; Durga Puja week (Sep-Oct) is the most vibrant","duration_days":1,"price_range_min":0,"price_range_max":400,"short_description":"Dhakeshwari, the national temple whose name gave Dhaka its own, keeps a living shakti tradition inside a moated courtyard in the city centre. Its twelfth-century origin, 1929 rebuild and autumn Durga Puja make it central to any heritage walk.","short_bn":"নদীর দেবী ঢাকেশ্বরীর নামেই ঢাকা - দ্বাদশ শতাব্দীর এই শাক্ত পীঠ পুকুরবেষ্টিত উঠোনে আজও চালু। বার্ষিক দুর্গাপূজায় শহরের আলোকসজ্জার কেন্দ্র এই মন্দিরই।","long_description":"Dhakeshwari, the national temple whose name gave Dhaka its own, keeps a living shakti tradition inside a moated courtyard in the city centre. Its twelfth-century origin, 1929 rebuild and autumn Durga Puja make it central to any heritage walk. The temple that gave Dhaka its name - 'goddess of the water' - with a twelfth-century origin and a 1929 rebuild inside a tank-surrounded courtyard. During Durga Puja the pandal circuit from Dhakeshwari through Old Dhaka is one of South Asia's great public festivals; visitors are welcome in the outer hall in modest dress.\n\nOn the ground: Living shakti shrine of old Dhaka; Courtyard tank and ritual baths; Durga Puja pandal route; Modern spire over older foundations; Nearby Islam Bagh and the Armenian church. GHORA GHURI guides rate the heritage, pilgrimage, architecture character of this place as the main reason to build a stop around it.\n\nReaching Dhakeshwari National Temple: Dhaka is within Dhaka city, connected by ride-share, CNG rickshaw, MRT Line 6 and local buses. Air: Hazrat Shahjalal International Airport (30-60 minutes in city traffic). Ground links run through Sayedabad and Gabtoli terminals for onward divisional travel.\n\nStaying over: expect hotels and serviced apartments across Gulshan, Banani, Dhanmondi and Old Dhaka.\n\nPlanning notes: the season window is October-March; Durga Puja week (Sep-Oct) is the most vibrant. Budget 0-400 BDT per person for a standard guided visit, and allow 1 day(s) on the ground. Bring water, a hat and patience: most brick monuments are open, shaded by little more than their own arcades, and a guide reads the site far better than any plaque.\n\nAll rates, opening hours and transport times in this listing are indicative and should be confirmed with Dhakeshwari National Temple site authorities before travel. GHORA GHURI keeps a local contact on call for Dhaka division itineraries and can arrange licensed guides, boat contracts and permits where they apply.","highlights":["Living shakti shrine of old Dhaka","Courtyard tank and ritual baths","Durga Puja pandal route","Modern spire over older foundations","Nearby Islam Bagh and the Armenian church"],"hook":"The temple that gave Dhaka its name - 'goddess of the water' - with a twelfth-century origin and a 1929 rebuild inside a tank-surrounded courtyard.","arrive":null,"stay":null,"plan":null,"extras":"During Durga Puja the pandal circuit from Dhakeshwari through Old Dhaka is one of South Asia's great public festivals; visitors are welcome in the outer hall in modest dress.","commons_category":"","featured":false,"image":"assets/images/destinations/dhakeshwari-temple.jpg","image_thumb":"assets/images/destinations/dhakeshwari-temple.thumb.jpg","image_remote":"","photo_credit":{"title":"File:Shiva temples Dhakeshwari Mandir 2 by Ragib Hasan.jpg","artist":"Ragib Hasan","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Shiva_temples_Dhakeshwari_Mandir_2_by_Ragib_Hasan.jpg"},"gallery":[{"local":"assets/images/destinations/dhakeshwari-temple.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/9/92/Shiva_temples_Dhakeshwari_Mandir_2_by_Ragib_Hasan.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","alt":"Dhakeshwari National Temple, Dhaka"},{"local":"assets/images/destinations/dhakeshwari-temple.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/9/92/Shiva_temples_Dhakeshwari_Mandir_2_by_Ragib_Hasan.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","alt":"Dhakeshwari National Temple, Dhaka"},{"local":"assets/images/destinations/dhakeshwari-temple.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/9/92/Shiva_temples_Dhakeshwari_Mandir_2_by_Ragib_Hasan.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","alt":"Dhakeshwari National Temple, Dhaka"}],"video_embed":"","sample_itinerary":[{"title":"Arrive, orient, first look","detail":"Reach Dhakeshwari National Temple by road. Settle in, then a short first walk at Living shakti shrine of old Dhaka before dinner in town. The guide briefs you on timings, ticket counters and where the light works late in the day."},{"title":"Slow morning and departure","detail":"Breakfast, one last look at Living shakti shrine of old Dhaka, then the return leg. Best time to be here is October-March; Durga Puja week (Sep-Oct) is the most vibrant, so plan the drive or boat around that window rather than the reverse."}]},{"id":"jatiya-sangsad-bhaban","slug":"jatiya-sangsad-bhaban","name":"Jatiya Sangsad Bhaban (Louis Kahn)","name_bn":"জাতীয় সংসদ ভবন","division":"Dhaka","district":"Dhaka","tags":["architecture","heritage","photography"],"latitude":23.749,"longitude":90.386,"best_time":"Year-round; dusk for the floodlights, weekends for the lake walk","duration_days":1,"price_range_min":0,"price_range_max":600,"short_description":"Louis Kahn's Jatiya Sangsad Bhaban in Ramna is among the twentieth century's most celebrated government buildings, and its lake, pylons and colonnades define central Dhaka. The exterior circuit is free and pairs with Ramna Park.","short_bn":"লুই কানের ডিজাইনে ১৯৮২ সালে শেষ হওয়া জাতীয় সংসদ ভবন আধুনিক স্থাপত্যের বিশ্বমানের নিদর্শন - হ্রদ, পাইলন আর ইট-মার্বেলের কোলোনেড। বাইরের পথ ধরে ঘোরা যায়, পাশেই রমনা।","long_description":"Louis Kahn's Jatiya Sangsad Bhaban in Ramna is among the twentieth century's most celebrated government buildings, and its lake, pylons and colonnades define central Dhaka. The exterior circuit is free and pairs with Ramna Park. Louis I. Kahn's parliament complex, finished in 1982, is a listed modern masterpiece - concrete, marble and brick colonnades arranged around a symbolic lake. Interior entry needs a parliamentary invitation, so most visits are exterior: the lake promenade, the Assembly square and the National Monument axis, best combined with Ramna Park.\n\nOn the ground: Kahn's geometric assembly pylons; Reflecting lake and ceremonial axis; Brick, marble and concrete layering; Ramna Park and Suhrawardy Udyan adjacent; Best photography in the last hour of light. GHORA GHURI guides rate the architecture, heritage, photography character of this place as the main reason to build a stop around it.\n\nReaching Jatiya Sangsad Bhaban (Louis Kahn): Dhaka is within Dhaka city, connected by ride-share, CNG rickshaw, MRT Line 6 and local buses. Air: Hazrat Shahjalal International Airport (30-60 minutes in city traffic). Ground links run through Sayedabad and Gabtoli terminals for onward divisional travel.\n\nStaying over: expect hotels and serviced apartments across Gulshan, Banani, Dhanmondi and Old Dhaka.\n\nPlanning notes: the season window is Year-round; dusk for the floodlights, weekends for the lake walk. Budget 0-600 BDT per person for a standard guided visit, and allow 1 day(s) on the ground.\n\nAll rates, opening hours and transport times in this listing are indicative and should be confirmed with Jatiya Sangsad Bhaban (Louis Kahn) site authorities before travel. GHORA GHURI keeps a local contact on call for Dhaka division itineraries and can arrange licensed guides, boat contracts and permits where they apply.","highlights":["Kahn's geometric assembly pylons","Reflecting lake and ceremonial axis","Brick, marble and concrete layering","Ramna Park and Suhrawardy Udyan adjacent","Best photography in the last hour of light"],"hook":"Louis I. Kahn's parliament complex, finished in 1982, is a listed modern masterpiece - concrete, marble and brick colonnades arranged around a symbolic lake.","arrive":null,"stay":null,"plan":null,"extras":"Interior entry needs a parliamentary invitation, so most visits are exterior: the lake promenade, the Assembly square and the National Monument axis, best combined with Ramna Park.","commons_category":"","featured":false,"image":"assets/images/destinations/jatiya-sangsad-bhaban.jpg","image_thumb":"assets/images/destinations/jatiya-sangsad-bhaban.thumb.jpg","image_remote":"","photo_credit":{"title":"File:Dhaka Nagar Bhaban.jpg","artist":"MD. FAZLA RABBE SARDER","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Dhaka_Nagar_Bhaban.jpg"},"gallery":[{"local":"assets/images/destinations/jatiya-sangsad-bhaban.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/67/Dhaka_Nagar_Bhaban.jpg/1920px-Dhaka_Nagar_Bhaban.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Jatiya Sangsad Bhaban (Louis Kahn), Dhaka"},{"local":"assets/images/destinations/jatiya-sangsad-bhaban.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/67/Dhaka_Nagar_Bhaban.jpg/1920px-Dhaka_Nagar_Bhaban.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Jatiya Sangsad Bhaban (Louis Kahn), Dhaka"},{"local":"assets/images/destinations/jatiya-sangsad-bhaban.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/67/Dhaka_Nagar_Bhaban.jpg/1920px-Dhaka_Nagar_Bhaban.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Jatiya Sangsad Bhaban (Louis Kahn), Dhaka"}],"video_embed":"","sample_itinerary":[{"title":"Arrive, orient, first look","detail":"Reach Jatiya Sangsad Bhaban (Louis Kahn) by road. Settle in, then a short first walk at Kahn's geometric assembly pylons before dinner in town. The guide briefs you on timings, ticket counters and where the light works late in the day."},{"title":"Slow morning and departure","detail":"Breakfast, one last look at Kahn's geometric assembly pylons, then the return leg. Best time to be here is Year-round; dusk for the floodlights, weekends for the lake walk, so plan the drive or boat around that window rather than the reverse."}]},{"id":"dhaka-university-curzon-hall","slug":"dhaka-university-curzon-hall","name":"Dhaka University, Curzon Hall & Arts Campus","name_bn":"ঢাকা বিশ্ববিদ্যালয় ও কার্জন হল","division":"Dhaka","district":"Dhaka","tags":["heritage","architecture","city","museum"],"latitude":23.7342,"longitude":90.3913,"best_time":"October-March; weekday mornings when the campus is calm","duration_days":1,"price_range_min":0,"price_range_max":800,"short_description":"Dhaka University's Ramna campus stacks a century of Bangla identity - Curzon Hall, the Shaheed Minar, the Fine Arts faculty, Nazrul's grave and Tagore's home - in walkable red-brick lanes twenty minutes from Gulshan.","short_bn":"রমনার ঢাকা বিশ্ববিদ্যালয় ক্যাম্পাস - কার্জন হল, ভাষা শহীদ মিনার, ফাইন আর্টস, নজরুলের কবর আর ট্যাগোরের আতিথ্য, সবই হাঁটা পথের মধ্যেই।","long_description":"Dhaka University's Ramna campus stacks a century of Bangla identity - Curzon Hall, the Shaheed Minar, the Fine Arts faculty, Nazrul's grave and Tagore's home - in walkable red-brick lanes twenty minutes from Gulshan. A 1921 foundation of red-brick Indo-Saracenic campus built around Curzon Hall, the Shaheed Minar, the museum of the Bangla Academy and the Faculty of Fine Arts with its open-air sculptures. The Language Movement Martyrs' Monument (1952), Kazi Nazrul Islam's grave at the university and Rabindranath Tagore's house at Pathuriaghat make this Bangladesh's most historically weighted square kilometre.\n\nOn the ground: Curzon Hall's Mughal-Gothic facade; Shaheed Minar of 1952 Language Movement; Bangla Academy and Fine Arts campus; Nazrul's grave and Tagore's house; Batalya Hill and the Red Mosque. GHORA GHURI guides rate the heritage, architecture, city character of this place as the main reason to build a stop around it.\n\nReaching Dhaka University, Curzon Hall & Arts Campus: Dhaka is within Dhaka city, connected by ride-share, CNG rickshaw, MRT Line 6 and local buses. Air: Hazrat Shahjalal International Airport (30-60 minutes in city traffic). Ground links run through Sayedabad and Gabtoli terminals for onward divisional travel.\n\nStaying over: expect hotels and serviced apartments across Gulshan, Banani, Dhanmondi and Old Dhaka.\n\nPlanning notes: the season window is October-March; weekday mornings when the campus is calm. Budget 0-800 BDT per person for a standard guided visit, and allow 1 day(s) on the ground. Bring water, a hat and patience: most brick monuments are open, shaded by little more than their own arcades, and a guide reads the site far better than any plaque.\n\nAll rates, opening hours and transport times in this listing are indicative and should be confirmed with Dhaka University, Curzon Hall & Arts Campus site authorities before travel. GHORA GHURI keeps a local contact on call for Dhaka division itineraries and can arrange licensed guides, boat contracts and permits where they apply.","highlights":["Curzon Hall's Mughal-Gothic facade","Shaheed Minar of 1952 Language Movement","Bangla Academy and Fine Arts campus","Nazrul's grave and Tagore's house","Batalya Hill and the Red Mosque"],"hook":"A 1921 foundation of red-brick Indo-Saracenic campus built around Curzon Hall, the Shaheed Minar, the museum of the Bangla Academy and the Faculty of Fine Arts with its open-air sculptures.","arrive":null,"stay":null,"plan":null,"extras":"The Language Movement Martyrs' Monument (1952), Kazi Nazrul Islam's grave at the university and Rabindranath Tagore's house at Pathuriaghat make this Bangladesh's most historically weighted square kilometre.","commons_category":"","featured":false,"image":"assets/images/destinations/dhaka-university-curzon-hall.jpg","image_thumb":"assets/images/destinations/dhaka-university-curzon-hall.thumb.jpg","image_remote":"","photo_credit":{"title":"File:Architecture of Curzon Hall 16.jpg","artist":"Wasiul Bahar","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Architecture_of_Curzon_Hall_16.jpg"},"gallery":[{"local":"assets/images/destinations/dhaka-university-curzon-hall.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Architecture_of_Curzon_Hall_16.jpg/1920px-Architecture_of_Curzon_Hall_16.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Dhaka University, Curzon Hall & Arts Campus, Dhaka"},{"local":"assets/images/destinations/dhaka-university-curzon-hall.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Architecture_of_Curzon_Hall_16.jpg/1920px-Architecture_of_Curzon_Hall_16.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Dhaka University, Curzon Hall & Arts Campus, Dhaka"},{"local":"assets/images/destinations/dhaka-university-curzon-hall.jpg","remote":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Architecture_of_Curzon_Hall_16.jpg/1920px-Architecture_of_Curzon_Hall_16.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","alt":"Dhaka University, Curzon Hall & Arts Campus, Dhaka"}],"video_embed":"","sample_itinerary":[{"title":"Arrive, orient, first look","detail":"Reach Dhaka University, Curzon Hall & Arts Campus by road. Settle in, then a short first walk at Curzon Hall's Mughal-Gothic facade before dinner in town. The guide briefs you on timings, ticket counters and where the light works late in the day."},{"title":"Slow morning and departure","detail":"Breakfast, one last look at Curzon Hall's Mughal-Gothic facade, then the return leg. Best time to be here is October-March; weekday mornings when the campus is calm, so plan the drive or boat around that window rather than the reverse."}]},{"id":"bashati-reserve-forest","slug":"bashati-reserve-forest","name":"Bashati Reserve Forest & Eco Park","name_bn":"বসতি রিজার্ভ ফরেস্ট","division":"Dhaka","district":"Gazipur","tags":["eco","city","family"],"latitude":23.8583,"longitude":90.4472,"best_time":"November-February; early morning or late afternoon","duration_days":1,"price_range_min":300,"price_range_max":1200,"short_description":"Bashati is Dhaka's surviving sal forest, now an eco-park with trails, a canopy walk and a small museum inside the Bashundhara residential belt. It gives city families and school groups a genuine woodland morning without leaving the metro area.","short_bn":"বসতি - ঢাকা-গাজীপুর করিডোরে শতাব্দীপ্রাচীন শালবন, এখন ট্রেইল, ক্যানোপি ওয়াক আর জাদুঘরসহ ইকো-পার্ক। উত্তর ঢাকার পরিবারের আধা দিনের সবচেয়ে সহজ সবুজ পাড়ি।","long_description":"Bashati is Dhaka's surviving sal forest, now an eco-park with trails, a canopy walk and a small museum inside the Bashundhara residential belt. It gives city families and school groups a genuine woodland morning without leaving the metro area. A 700-year-old forest on the Dhaka-Gazipur corridor, kept as a green lung and eco-park with a canopy walk, deer enclosure and an eco-museum. Reached from the Dhaka-Mymensingh highway near Bashundhara; it is the closest real forest to the capital and the standard family half-day for north-Dhaka residents.\n\nOn the ground: Canopy walk and nature trail; Deer enclosure and eco-museum; Old growth sal and teak stand; Cycle track and open lawns; Twenty-five minutes from Uttara. GHORA GHURI guides rate the eco, city, family character of this place as the main reason to build a stop around it.\n\nReaching Bashati Reserve Forest & Eco Park: Gazipur is 25-45 minutes north of Dhaka via the Dhaka-Tangail highway. Air: Shahjalal International Airport, about 25 minutes. Ground links run through Baburhat bus stand on the Dhaka-Tangail highway.\n\nStaying over: expect resort-style resorts around Sawar and Joydebpur, most open for day visitors.\n\nPlanning notes: the season window is November-February; early morning or late afternoon. Budget 300-1,200 BDT per person for a standard guided visit, and allow 1 day(s) on the ground. This is community-run territory. Book through the local committee, keep to marked trails and buy food and craft locally so the visit pays the people protecting the site.\n\nAll rates, opening hours and transport times in this listing are indicative and should be confirmed with Bashati Reserve Forest & Eco Park site authorities before travel. GHORA GHURI keeps a local contact on call for Dhaka division itineraries and can arrange licensed guides, boat contracts and permits where they apply.","highlights":["Canopy walk and nature trail","Deer enclosure and eco-museum","Old growth sal and teak stand","Cycle track and open lawns","Twenty-five minutes from Uttara"],"hook":"A 700-year-old forest on the Dhaka-Gazipur corridor, kept as a green lung and eco-park with a canopy walk, deer enclosure and an eco-museum.","arrive":null,"stay":null,"plan":null,"extras":"Reached from the Dhaka-Mymensingh highway near Bashundhara; it is the closest real forest to the capital and the standard family half-day for north-Dhaka residents.","commons_category":"","featured":false,"image":"","image_thumb":"","image_remote":"","photo_credit":null,"gallery":[{"local":"","remote":"https://picsum.photos/seed/bashati-reserve-forest-1/1200/800.jpg","alt":"Bashati Reserve Forest & Eco Park - illustrative view 1"},{"local":"","remote":"https://picsum.photos/seed/bashati-reserve-forest-2/1200/800.jpg","alt":"Bashati Reserve Forest & Eco Park - illustrative view 2"},{"local":"","remote":"https://picsum.photos/seed/bashati-reserve-forest-3/1200/800.jpg","alt":"Bashati Reserve Forest & Eco Park - illustrative view 3"}],"video_embed":"","sample_itinerary":[{"title":"Arrive, orient, first look","detail":"Reach Bashati Reserve Forest & Eco Park by road. Settle in, then a short first walk at Canopy walk and nature trail before dinner in town. The guide briefs you on timings, ticket counters and where the light works late in the day."},{"title":"Slow morning and departure","detail":"Breakfast, one last look at Canopy walk and nature trail, then the return leg. Best time to be here is November-February; early morning or late afternoon, so plan the drive or boat around that window rather than the reverse."}]}],"lite-packages":[{"id":"sundarban-3n","title":"Sundarbans: Three Nights on the Mangrove Rivers","title_bn":"সুন্দরবন: তিন রাতের নৌভ্রমণ","division":"Khulna","badge":"Best seller","duration_days":4,"nights":3,"price_min":13900,"price_max":22500,"rating":4.9,"reviews":212,"group_size":"2 - 18 (shared departures cap at 18)","languages":"Bangla, English","meals":"Full board on board","tags":["eco","wildlife","river","heritage"],"featured":true,"summary":"A licensed vessel, an approved forest route and three nights between Katka, Haringata and Dublar Char - deer at dusk, kingfishers at first light, and Bagerhat’s Sixty Dome Mosque on the way in.","stops":["Khulna","Noapara Ghat","Katka","Haringata","Dublar Char","Mongla","Bagerhat"],"destination_ids":["sundarbans","katka-arpi-char","shat-gombuj-mosque","bagerhat-mosque-city-walk","dhaluttar-bon","mongla-beach-port"],"itinerary":[{"title":"1 — Khulna to Noapara, first boat day","detail":"Pick-up at Khulna railway station or your hotel, brief safety and permit check at the Noapara counter, board the licensed vessel, sail the Shibsa to Katka. Evening walk on the estuarine beach; forest-registered guide on board throughout."},{"title":"2 — Katka to Haringata","detail":"Sunrise from the Katka watchtower, then a small-boat push into the narrow creeks where the banks close in. Afternoon at Haringata’s deer breeding area, and a late-afternoon char walk for spotted deer and wild boar tracks. No night spotlighting: it is prohibited and we do not arrange it."},{"title":"3 — Dublar Char day","detail":"Cross to Dublar Char, the big sandbank with its seasonal fishing camp, oyster beds and gharial banking area. Swim only where the crew choose the sandbar; lunch on board; return sail at golden hour."},{"title":"4 — Mongla, Bagerhat and the drive back","detail":"Disembark at Mongla, visit the Sixty Dome Mosque and the Bagerhat mosque-city lane walk with an archaeology-trained guide, then transfer to Khulna or Dhaka. Add a night in Khulna if you would rather not drive on."}],"included":["Forest-department permit filing and entry fees","Licensed cabin cruiser or mining boat, shared twin cabin with attached bath","All meals on board (Bangla, vegetarian available)","Forest-registered guide and boat crew","Khulna hotel on night 1 and airport/rail transfers","Bagerhat guided visit and tickets","Fuel, driver allowance, and one bottled-water refill station per port"],"excluded":["Alcohol (not permitted in the reserve)","Soft drinks and laundry on board","Tips for crew and guide","Hotel upgrades in Khulna","Travel insurance","Anything not listed as included"],"departure_dates":[{"date":"2026-11-12","seats":9,"price":13900},{"date":"2026-12-10","seats":4,"price":15900},{"date":"2027-01-14","seats":13,"price":14900},{"date":"2027-02-11","seats":18,"price":13900}],"image":"assets/images/destinations/sundarbans.jpg"},{"id":"sundarban-day-1d","title":"Sundarbans Day Run from Khulna","title_bn":"খুলনা থেকে একদিনের সুন্দরবন","division":"Khulna","badge":"Short & sharp","duration_days":1,"nights":0,"price_min":3400,"price_max":5200,"rating":4.6,"reviews":96,"group_size":"4 - 30","languages":"Bangla, English","meals":"Breakfast + lunch","tags":["eco","river","photography"],"featured":true,"summary":"For travellers with one day and a real wish to see mangrove forest: dawn boat from Noapara, two creeks, a watchtower, lunch on board, back by late afternoon.","stops":["Khulna","Noapara Ghat","Katka"],"destination_ids":["sundarbans","katka-arpi-char","mongla-beach-port"],"itinerary":[{"title":"1 — Full day on the Shibsa","detail":"06:00 pick-up in Khulna, 07:00 boat departure, creek navigation while the banks are still active with kingfishers and mudskippers, watchtower climb at Katka, rice and fish lunch on board, afternoon return via the shrimp-pond fringe. 17:00 drop-off. Boat capacity and permit counters close at dusk, so the schedule is fixed."}],"included":["Shared boat with licensed crew","Forest permit and entry fees","Guide","Breakfast tea and Bengali lunch","Khulna hotel/railway transfers"],"excluded":["Overnight costs","Tips","Insurance","Private boat charter (add Tk 6,500)"],"departure_dates":[{"date":"2026-11-15","seats":22,"price":3400},{"date":"2026-12-13","seats":16,"price":3900},{"date":"2027-01-17","seats":28,"price":3400}],"image":"assets/images/destinations/sundarbans.jpg"},{"id":"coast-4d","title":"Cox’s Bazar, Himchari, Inani & Teknaf","title_bn":"কক্সবাজার, হিমছড়ি, ইনানি ও টেকনাফ","division":"Chattogram","badge":"Beach classic","duration_days":4,"nights":3,"price_min":9900,"price_max":16500,"rating":4.7,"reviews":188,"group_size":"2 - 18","languages":"Bangla, English","meals":"Breakfast + dinner","tags":["beach","hill","photography","family"],"featured":true,"summary":"The 120 km beach done properly: midweek slots, sunrise at Himchari’s waterfall and temple, Inani’s low-tide rock shelves, then the boat to St. Martin’s if the weather window holds.","stops":["Cox’s Bazar","Himchari","Khuni Khular Pukhur","Inani","Teknaf"],"destination_ids":["coxsbazar-sea-beach","himchari","sugandha-khuni-pahar","inani-beach","teknaf-saint-martin"],"itinerary":[{"title":"1 — Arrive, Sugandha point and the laboni swing","detail":"Flight or night-bus arrival, check in at Laboni/Kolatoli, late-afternoon walk to Sugandha where the beach narrows against the hill, seafood market briefing (buy at the counter, have it cooked, agree the price first)."},{"title":"2 — Himchari and Khuni Khular Pukhur","detail":"Early start up the ridge: Himchari waterfall (seasonal), the hill-top temple, and the hidden lagoon of Khuni Khular Pukhur behind the dunes. Macaque etiquette is covered on the way in - no food in hand, no plastic bags."},{"title":"3 — Inani morning, Teknaf afternoon","detail":"Low tide at Inani for the rock shelves and black coral fragments exposed on the reef flat (walk in shoes, do not break or take any). Afternoon in Teknaf: the twin-ridge viewpoint, the Birmindia border marker view, and the sunset boat."},{"title":"4 — Departure, or extend to St. Martin’s","detail":"Morning free for the beach, then transfer out. Guests adding St. Martin’s take the 09:00 launch from Teknaf and rejoin the return schedule two nights later."}],"included":["Three nights beachfront hotel (standard or twin sharing)","Daily breakfast and three dinners","Private AC vehicle with driver for all sightseeing","English- or Bangla-speaking local guide","Entry fees for Himchari and the lagoon area","Fuel, parking and driver allowance"],"excluded":["Domestic flights / long-distance bus tickets","Launch tickets to St. Martin’s (Tk 2,200 return, weather-dependent)","Lunches and seafood","Parasailing and jet-ski operators","Tips","Insurance"],"departure_dates":[{"date":"2026-11-05","seats":11,"price":9900},{"date":"2026-12-19","seats":3,"price":14500},{"date":"2027-02-06","seats":15,"price":10500}],"image":"assets/images/destinations/coxsbazar-sea-beach.jpg"},{"id":"st-martin-2n","title":"St. Martin’s Island Weekend","title_bn":"সেন্টমার্টিন দ্বীপ","division":"Chattogram","badge":"Seasonal","duration_days":3,"nights":2,"price_min":8600,"price_max":13800,"rating":4.5,"reviews":143,"group_size":"2 - 30 (launch seats are limited)","languages":"Bangla, English","meals":"Breakfast + dinner","tags":["beach","island","eco","photography"],"featured":true,"summary":"Two nights on the coral island with a timed landing at Chhera, a cycle round the main road, and the rules that keep the reef intact - which also explains why the season is only October to May.","stops":["Teknaf","Chhera Island","Martin’s Beach"],"destination_ids":["saint-martins-island","teknaf-saint-martin"],"itinerary":[{"title":"1 — Teknaf to the island","detail":"Morning assembly at Teknaf jetty, 09:00 launch crossing (about 1 h 40 m), check-in at the resort or guesthouse block, evening on the east beach where the sand is still white after the day-trippers leave."},{"title":"2 — Chhera at low tide, island by bicycle","detail":"Boat to Chhera timed to the published low water so the coral shelf is exposed for a short, shoe-on snorkel and nothing is touched or lifted. Return to Martin’s for an afternoon cycling the single road: coconut groves, the small Hindu temple at Uttar para, the mangrove fringe at the south end."},{"title":"3 — Island morning and return launch","detail":"Sunrise on the west sand - the quiet side, where the overnight tide has laid down a fresh shelf and nobody is standing on it yet. Breakfast at 08:00, rooms vacated by 09:30, the 11:00 launch back to Teknaf, then the transfer to Cox’s Bazar airport or the night bus to Dhaka. If the launch is cancelled for weather the day becomes a coast-road return and we hold the hotel either way."}],"included":["Return launch Teknaf-Martin’s with reserved seats","Two nights shared resort accommodation","Breakfast and dinner both days","Chhera boat with timed landing permit","Bicycle for the island loop","Guide and transfers in Teknaf"],"excluded":["Anything not listed","Scuba or glass-bottom boat (we do not sell reef-contact activities)","Plastic-bottled water on the island (refill points listed on arrival)","Tips","Insurance"],"departure_dates":[{"date":"2026-11-20","seats":8,"price":8600},{"date":"2026-12-26","seats":2,"price":12400},{"date":"2027-01-23","seats":20,"price":9400}],"image":"assets/images/destinations/saint-martins-island.jpg"}]};
